with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('gå på pension', 'phrase', 'd1e41a5f-96c4-540c-b595-ae70e630f21c', 1, 'verb', null, 'to retire', 'Min far gik på pension sidste år.', 'My father retired last year.'), ('være sammen', 'phrase', '0079a5c6-a94b-50b1-a09e-0f4e6df66c82', 1, 'verb', null, 'to be together (in a relationship)', 'De har været sammen i tre år.', 'They have been together for three years.'), ('være sammen', 'phrase', '04607ac2-07b8-55b3-bcb4-d557c6aa06d1', 2, 'verb', null, 'to be together (spend time)', 'Børnene er sammen hver dag efter skole.', 'The children are together every day after school.'), ('slå op', 'phrase', 'd2b28152-fa62-59d1-acdb-f6221da804c6', 1, 'verb', null, 'to break up (with a partner)', 'De slog op efter tre år sammen.', 'They broke up after three years together.'), ('holde øje med', 'phrase', 'd15c26d3-ee46-55c1-a57c-7d83275ed8a9', 1, 'verb', null, 'to keep an eye on', 'Kan du holde øje med min taske mens jeg henter kaffe?', 'Can you keep an eye on my bag while I pick up coffee?'), ('gå tur', 'phrase', '8dff40f3-c4fa-5c6e-9250-f50e221c0432', 1, 'verb', null, 'to go for a walk', 'Vi gik tur langs stranden i aftes.', 'We went for a walk along the beach yesterday evening.'), ('blive til virkelighed', 'phrase', 'f4061e29-5609-5397-b919-5cf9351bb753', 1, 'verb', null, 'to come true, to become reality', 'Drømmen om et hus ved havet blev til virkelighed sidste år.', 'The dream of a house by the sea became a reality last year.'), ('på trods af', 'phrase', 'ec3f9a65-02fc-50f5-9a66-23b342e9767a', 1, 'preposition', null, 'despite', 'På trods af regnen gik vi en tur.', 'Despite the rain, we went for a walk.'), ('træde tilbage', 'phrase', 'f6bc78be-1002-5bf4-bc4c-6c38c86b59a1', 1, 'verb', null, 'to step back (physically)', 'Han trådte tilbage for at give plads.', 'He stepped back to make room.'), ('forberede sig', 'phrase', 'e59d1284-02a2-54d5-8df9-2f107a01d87a', 1, 'verb', null, 'to prepare (oneself)', 'Hun forberedte sig til eksamen hele weekenden.', 'She prepared for the exam all weekend.'), ('klage over', 'phrase', '742301fe-06a1-5af8-adf9-6964875a525e', 1, 'verb', null, 'to complain about', 'Hun klager over maden hver dag.', 'She complains about the food every day.'), ('godt nytår', 'phrase', '8e1fdaf3-806a-5ae5-9587-9e977b6c0b3d', 1, 'phrase', null, 'Happy New Year', 'Jeg ønsker dig et godt nytår.', 'I wish you a happy New Year.'), ('vaske sig', 'phrase', '4bebe940-76ef-57e1-844c-a9f1575dcf82', 1, 'verb', null, 'to wash oneself', 'Jeg vasker mig hver morgen.', 'I wash myself every morning.'), ('skrive under', 'phrase', 'e90f14f0-3c45-5486-acd1-5ecbd12ee8f3', 1, 'verb', null, 'to sign', 'Hun skrev under på kontrakten i går.', 'She signed the contract yesterday.'), ('falde sammen', 'phrase', '45405a9b-00f7-53e4-b6cb-4bebe5721e12', 1, 'verb', null, 'to collapse (of a building)', 'Det gamle hus faldt sammen under stormen.', 'The old house collapsed during the storm.'), ('prøve på', 'phrase', '35877699-321f-524d-b2c6-51549287b033', 1, 'verb', null, 'to try (to do something)', 'Hun prøver på at lære dansk.', 'She is trying to learn Danish.'), ('skifte mening', 'phrase', 'ada1c133-59a3-52be-96eb-f295f6a5a1dd', 1, 'verb', null, 'to change one''s mind', 'Jeg skiftede mening om filmen efter at have set den igen.', 'I changed my mind about the movie after watching it again.'), ('kigge ud', 'phrase', '4fdb8279-a664-5464-8b94-3d6d2e7e6d1c', 1, 'verb', null, 'to look out', 'Han kigger ud ad vinduet hver morgen.', 'He looks out the window every morning.'), ('interessere sig for', 'phrase', '755f0811-09e3-555a-ab3b-559a1cc9800a', 1, 'verb', null, 'to be interested in', 'Hun interesserer sig for dansk historie.', 'She is interested in Danish history.'), ('sørge for', 'phrase', '1a617e1d-6d55-5514-81a7-f819b64545d4', 1, 'verb', null, 'to ensure, to make sure', 'Jeg sørger for, at døren er låst.', 'I make sure the door is locked.'), ('sørge for', 'phrase', '71fe7ce9-3dc4-55d5-8eb8-ee3247f5b918', 2, 'verb', null, 'to arrange, to provide', 'De sørgede for mad til alle gæsterne.', 'They provided food for all the guests.'), ('blande sig', 'phrase', '5af57b52-d8cb-564a-9da0-372ef9e1f9f1', 1, 'verb', null, 'to interfere', 'Hun blander sig altid i vores samtaler.', 'She always interferes in our conversations.'), ('indflydelse på', 'phrase', '15632443-1080-5854-abb2-5b8345037241', 1, 'phrase', null, 'influence on', 'Hendes mening har stor indflydelse på beslutningen.', 'Her opinion has a big influence on the decision.'), ('holde jul', 'phrase', 'c7be6092-f903-5b72-8472-4723bf224d6c', 1, 'verb', null, 'to celebrate Christmas', 'Vi holder jul hos mine forældre i år.', 'We are spending Christmas at my parents'' place this year.'), ('blive skilt', 'phrase', 'b4cb5fa4-179f-5433-9a4d-084ffc22417b', 1, 'verb', null, 'to get divorced', 'De blev skilt efter ti års ægteskab.', 'They divorced after ten years of marriage.'), ('begå selvmord', 'phrase', 'fd8d83e3-3a20-5f26-a31a-47453f5d49a8', 1, 'verb', null, 'to commit suicide', 'Hun begik selvmord efter en lang depression.', 'She committed suicide after a long depression.'), ('holde kæft', 'phrase', 'abf606fe-c06f-5eb1-ae88-a99d24c07f1c', 1, 'verb', null, 'to shut up (rude)', 'Hold kæft og lyt til læreren.', 'Shut up and listen to the teacher.'), ('se frem til', 'phrase', 'b122dd1f-26dd-56dc-a1ee-5d534cc8a93c', 1, 'verb', null, 'to look forward to', 'Jeg ser frem til ferien.', 'I''m looking forward to the holidays.'), ('få at vide', 'phrase', 'ff245af3-0ed8-56fe-a33f-5766a26d8973', 1, 'verb', null, 'to be told (receive information)', 'Jeg fik at vide, at mødet er aflyst.', 'I was told that the meeting has been cancelled.'), ('klare sig', 'phrase', 'cc1e69d5-1820-57b3-8c64-73233173bc52', 1, 'verb', null, 'to manage', 'Jeg tror, at hun klarer sig fint på det nye job.', 'I think she''ll do well in her new job.'), ('høre efter', 'phrase', 'b5734c26-6ae0-503c-b222-96f57c8fc193', 1, 'verb', null, 'to listen (carefully)', 'Børnene hører efter, når læreren taler.', 'The children listen when the teacher speaks.'), ('falde ned', 'phrase', 'fe663d58-7521-5bb9-bad5-99e4bbc67c6d', 1, 'verb', null, 'to fall down', 'Bogen faldt ned fra bordet.', 'The book fell off the table.'), ('vende tilbage til', 'phrase', 'e758595f-3619-5fff-9b7c-ce67b424e317', 1, 'verb', null, 'to return to (a topic, place)', 'Vi vender tilbage til emnet i morgen.', 'We will return to the subject tomorrow.'), ('gå væk', 'phrase', '4d68f3d3-6f15-5b25-88c9-59a65123bd06', 1, 'verb', null, 'to go away (of stain, pain)', 'Pletten på skjorten gik væk i vask.', 'The stain on the shirt went away in the wash.'), ('løbe ud', 'phrase', '070ed4a8-9a73-5f8e-8683-50efd577741c', 1, 'verb', null, 'to expire', 'Mit pas løb ud i sidste uge.', 'My passport expired last week.'), ('løbe ud', 'phrase', 'bf6ee3f4-5031-52ec-b21c-139bca6bbc6a', 2, 'verb', null, 'to run out (of liquid)', 'Vandet løber ud af spanden.', 'The water runs out of the bucket.'), ('bryde ind', 'phrase', '31aa2bf8-b6a6-530b-b1b4-8393c7ae695b', 1, 'verb', null, 'to break in (enter forcibly)', 'Tyven brød ind i huset om natten.', 'The thief broke into the house at night.'), ('bryde ud i', 'phrase', '5420a712-2d79-5560-994f-45eb73dd0ed1', 1, 'verb', null, 'to burst into (laughter, applause, etc.)', 'Publikum brød ud i klapsalver.', 'The audience erupted in applause.'), ('næste stop', 'phrase', '5e1a4bdc-eb8e-5f03-9d44-02d8913d70af', 1, 'verb', null, 'next stop (on transport)', 'Næste stop er hovedbanegården.', 'The next stop is the Central Station.'), ('koncentrere sig', 'phrase', '63dcab2b-f776-54d6-9db3-58c815684af8', 1, 'verb', null, 'to concentrate', 'Jeg kan ikke koncentrere mig, når der er så meget larm.', 'I can''t concentrate when there''s so much noise.'), ('bøde for', 'phrase', 'd01c3d07-ffe8-5c3c-814a-1dbd9be80c1f', 1, 'verb', null, 'to pay the price (for)', 'Han bøder for sine fejl hver dag.', 'He pays for his mistakes every day.'), ('gå bort', 'phrase', '76fe24a4-9d85-5868-a63d-ff86150db32e', 1, 'verb', null, 'to pass away', 'Min nabo gik bort i sidste uge.', 'My neighbor passed away last week.'), ('være ligeglad med', 'phrase', '8a6b580c-9b97-58e5-b4cd-a6e483df3634', 1, 'verb', null, 'to not care about', 'Jeg er ligeglad med, hvad de andre tænker.', 'I don''t care what the others think.'), ('skjule sig', 'phrase', '44117296-28f2-519c-99bb-6244b9c4b11d', 1, 'verb', null, 'to hide (oneself)', 'Katten skjuler sig under bordet.', 'The cat hides under the table.'), ('hilse på', 'phrase', '7073886d-9eb5-5325-ba14-1728cb54c62f', 1, 'verb', null, 'to greet (upon meeting)', 'Jeg hilser på min nabo hver morgen.', 'I say hello to my neighbour every morning.'), ('sige op', 'phrase', '9786a514-1216-557d-b34c-4634ac5f97b8', 1, 'verb', null, 'to resign (from a job)', 'Hun sagde op i går.', 'She resigned yesterday.'), ('samle på', 'phrase', '5c277298-ef87-55e0-a06f-9b6b93667229', 1, 'verb', null, 'to collect', 'Min bedstefar samler på gamle mønter.', 'My grandfather collects old coins.'), ('redde liv', 'phrase', 'f3fe99c4-383d-5c02-8cf4-6ca3fa98521b', 1, 'verb', null, 'to save lives', 'Lægen reddede liv på hospitalet i nat.', 'The doctor saved lives at the hospital last night.'), ('basere på', 'phrase', '56f795d2-2f02-51e5-84ad-6c2fdf0b0461', 1, 'verb', null, 'to base on', 'Filmen er baseret på en sand historie.', 'The film is based on a true story.'), ('kende til', 'phrase', '2bbbbd4d-2279-5a9a-8de2-149dee724568', 1, 'verb', null, 'to know of', 'Jeg kender til en god restaurant i nærheden.', 'I know of a good restaurant nearby.'), ('frygte for', 'phrase', 'c49ebdfe-be32-55a0-bab7-d279b0dc5f9d', 1, 'verb', null, 'to fear for', 'Jeg frygter for hans helbred efter ulykken.', 'I fear for his health after the accident.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0003' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
